-- SMARTPRICE v2.0 ENTERPRISE ALPHA 1
begin;
create extension if not exists pgcrypto;
create table if not exists public.smartprice_connectors (id uuid primary key default gen_random_uuid(),store_id uuid not null references public.stores(id) on delete cascade,connector_type text not null default 'caissekom',api_url text not null,api_key_encrypted text,frequency_minutes integer,enabled boolean not null default true,sync_fields jsonb not null default '["products","prices"]'::jsonb,last_test_at timestamptz,last_test_status text,last_sync_at timestamptz,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(store_id,connector_type));
create table if not exists public.smartprice_sync_runs (id uuid primary key default gen_random_uuid(),connector_id uuid references public.smartprice_connectors(id) on delete set null,store_id uuid not null references public.stores(id) on delete cascade,status text not null check(status in ('running','success','partial','failed')),started_at timestamptz not null default now(),finished_at timestamptz,added_rows integer not null default 0,updated_rows integer not null default 0,error_rows integer not null default 0,message text,technical_details jsonb not null default '{}'::jsonb);
alter table public.smartprice_connectors enable row level security;alter table public.smartprice_sync_runs enable row level security;drop policy if exists "sp connectors alpha" on public.smartprice_connectors;create policy "sp connectors alpha" on public.smartprice_connectors for all to anon,authenticated using(true) with check(true);drop policy if exists "sp sync alpha" on public.smartprice_sync_runs;create policy "sp sync alpha" on public.smartprice_sync_runs for all to anon,authenticated using(true) with check(true);grant select,insert,update,delete on public.smartprice_connectors,public.smartprice_sync_runs to anon,authenticated;commit;notify pgrst,'reload schema';
